<template>
  <div class="space-y-6">
    <div class="flex items-center justify-between">
      <h2 class="text-xl font-bold text-ink-gray-9">Applications</h2>
      <Button variant="solid" @click="showInstallModal = true">
        Install App
      </Button>
    </div>

    <!-- App List -->
    <div class="grid grid-cols-1 gap-6 md:grid-cols-2 lg:grid-cols-3">
      <AppCard
