        :key="app.name"
        :app="app"
        @update="handleUpdate"
        @uninstall="handleUninstall"
      />
      <div v-if="!apps.data?.length && !apps.loading" class="col-span-full py-20 text-center border-2 border-dashed rounded-xl">
        <Package class="mx-auto h-12 w-12 text-ink-gray-3" />
        <h3 class="mt-4 text-sm font-semibold text-ink-gray-9">No apps installed</h3>
        <p class="mt-1 text-sm text-ink-gray-5">Fetch or install apps to view them here.</p>
      </div>
    </div>

    <InstallAppModal
      v-model="showInstallModal"
      @installed="apps.reload()"
    />
  </div>
</template>

<script setup>
