<template>
  <Dialog
    v-bind="$attrs"
    title="Install App"
    size="md"
  >
    <template #body>
      <div class="space-y-4">
        <FormControl label="App URL (GitHub)">
          <TextInput v-model="form.url" placeholder="https://github.com/user/app" />
        </FormControl>
        <FormControl label="Target Bench">
          <TextInput v-model="form.bench" placeholder="Select bench..." />
        </FormControl>
      </div>
    </template>
    <template #actions>
      <div class="flex gap-2">
        <Button variant="subtle" @click="$emit('update:modelValue', false)">
          Cancel
        </Button>
        <Button variant="solid" :loading="loading" @click="handleInstall">
          Install
        </Button>
      </div>
    </template>
  </Dialog>
</template>

<script setup>
import { reactive, ref } from "vue"

const emit = defineEmits(["update:modelValue", "installed"])
const loading = ref(false)
const form = reactive({
	url: "",
	bench: "",
})

async function handleInstall() {
	loading.value = true
	// In reality, call API here
	setTimeout(() => {
		loading.value = false
		emit("installed")
		emit("update:modelValue", false)
	}, 1000)
}
</script>
